<?php
require_once 'includes/functions.php'; require_login(); if(!is_admin()){http_response_code(403);exit('Akses ditolak');} page_title('Produk & Unit');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$unit=(int)($_POST['unit_id']??0);$price=(float)($_POST['price']??0);$label=trim($_POST['unit_label']??'pcs');$desc=trim($_POST['description']??'');
 if($name && $unit && $price>=0){$pdo->prepare("INSERT INTO products(unit_id,name,description,price,unit_label) VALUES(?,?,?,?,?)")->execute([$unit,$name,$desc,$price,$label]);log_activity('Tambah produk',$name);flash('Produk berhasil ditambahkan.');header('Location: products.php');exit;}else $error='Lengkapi data produk.';}
$units=$pdo->query("SELECT * FROM business_units ORDER BY id")->fetchAll();$rows=$pdo->query("SELECT p.*,b.name unit_name FROM products p JOIN business_units b ON b.id=p.unit_id ORDER BY p.id DESC")->fetchAll();
include 'includes/header.php'; ?>
<div class="page-head"><div><h1>Produk & Unit Usaha</h1><p class="sub">Kelola katalog harga awal setiap unit.</p></div></div>
<div class="grid two-col"><div class="card"><h2 class="section-title">Tambah Produk / Layanan</h2><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><div class="field"><label>Unit Usaha</label><select name="unit_id" required><?php foreach($units as $u): ?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach; ?></select></div><div class="field" style="margin-top:12px"><label>Nama Produk</label><input name="name" required></div><div class="field" style="margin-top:12px"><label>Deskripsi</label><textarea name="description"></textarea></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Harga</label><input type="number" name="price" min="0" required></div><div class="field"><label>Satuan</label><input name="unit_label" value="pcs" required></div></div><button class="btn" style="margin-top:16px">Simpan Produk</button></form></div>
<div class="card"><h2 class="section-title">Katalog Terdaftar</h2><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Unit</th><th>Harga</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['unit_name'])?></td><td><?=rupiah($r['price'])?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
